import { d as db } from "../../../../chunks/db.js";
import { g as getEmpresaId } from "../../../../chunks/get-empresa-id.js";
import { s as serialize } from "../../../../chunks/utils3.js";
const load = async ({ request, url }) => {
  try {
    const empresaId = await getEmpresaId(request);
    const page = parseInt(url.searchParams.get("page") || "1");
    const limit = parseInt(url.searchParams.get("limit") || "10");
    const currentPage = page > 0 ? page : 1;
    const itemsPerPage = [1, 5, 10, 25, 50, 100].includes(limit) ? limit : 10;
    const skip = (currentPage - 1) * itemsPerPage;
    const [totalVendas, totalFinalizada, totalRascunho] = await Promise.all([
      db.venda.count({ where: { empresaId } }),
      db.venda.count({ where: { empresaId, status: "FINALIZADA" } }),
      db.venda.count({ where: { empresaId, status: "FACTURADO" } })
    ]);
    const totalPages = Math.ceil(totalVendas / itemsPerPage);
    const vendas = await db.venda.findMany({
      where: { empresaId },
      include: {
        cliente: true,
        usuario: {
          select: {
            id: true,
            name: true,
            email: true
          }
        },
        itens: {
          include: {
            produto: {
              include: { taxa: true }
            }
          }
        }
      },
      orderBy: { criadoEm: "desc" },
      skip,
      take: itemsPerPage
    });
    const totalReceita = await db.venda.aggregate({
      where: { empresaId, status: "FINALIZADA" },
      _sum: {
        total: true
      }
    });
    return serialize({
      vendas,
      paginacao: {
        currentPage,
        itemsPerPage,
        totalItems: totalVendas,
        totalPages,
        hasNextPage: currentPage < totalPages,
        hasPrevPage: currentPage > 1
      },
      estatisticas: {
        total: totalVendas,
        finalizada: totalFinalizada,
        rascunho: totalRascunho,
        receita: totalReceita._sum.total || 0
      }
    });
  } catch (error) {
    console.error("Erro ao carregar vendas:", error);
    return {
      vendas: [],
      paginacao: {
        currentPage: 1,
        itemsPerPage: 10,
        totalItems: 0,
        totalPages: 0,
        hasNextPage: false,
        hasPrevPage: false
      },
      estatisticas: {
        total: 0,
        finalizada: 0,
        rascunho: 0,
        receita: 0
      }
    };
  }
};
export {
  load
};
